    for (int k = 0; k < MAP_N; k++)
        if (mp[k].valid) {
            double a = mp[k].pw[0] - pf[0], b = mp[k].pw[1] - pf[1], c = mp[k].pw[2] - pf[2];
            if (a * a + b * b + c * c < 0.25 * 0.25) return;
        }
