        tm /= MAP_PS * MAP_PS;
        for (int i = 0; i < MAP_PS * MAP_PS; i++) { double q = m->t[i] - tm; tn += q * q; }
        if (tn < 1e-6 * MAP_PS * MAP_PS) continue;
